        "back": "يربط القانون بينهما بجعل معامل كل مادة متفاعلة أو ناتجة في المعادلة الكيميائية الموزونة أُسّاً (قوة) يُرفع إليه التركيز المولاري لتلك المادة في تعبير ثابت الاتزان (حاصل ضرب تراكيز النواتج مقسوماً على حاصل ضرب تراكيز المتفاعلات).",
