        "back": "الشرط هو ثبات \"درجة الحرارة\"؛ لأن قيمة ثابت الاتزان تعتمد مباشرة عليها وتتغير بتغيرها (لكل درجة حرارة قيمة ثابت اتزان خاصة بها)، بينما لا تتأثر بالتغير في التراكيز الابتدائية للمواد.",
        "level": "Medium"
