        "back": "من حيث نوع المواد: يمثل البسط حاصل ضرب تراكيز المواد الناتجة مرفوعة لأسس معاملاتها، بينما يمثل المقام حاصل ضرب تراكيز المواد المتفاعلة مرفوعة لأسس معاملاتها.",
