    "summary": "يبدأ الدرس بتوضيح مفهوم التأين الذاتي للماء، وهو سلوك تسلك فيه بعض جزيئات الماء كحموض وبعضها الآخر كقواعد في الماء نفسه، مما ينتج تراكيز متساوية ضئيلة جداً من أيونات الهيدرونيوم [H3O+] وأيونات الهيدروكسيد [OH-]. ويتم التعبير عن هذا الاتزان الكيميائي باستخدام ثابت تأين الماء (Kw) الذي يساوي 1x10^-14 عند درجة حرارة 25 مئوية، وهو ما يتيح تصنيف المحاليل إلى حمضية، أو قاعدية، أو متعادلة بناءً على تراكيز هذه الأيونات.\n\nينتقل الدرس بعد ذلك إلى دراسة محاليل الحموض القوية مثل حمض الهيدروكلوريك والنيتريك والبيركلوريك، حيث تتميز هذه الحموض بقدرتها على التأين الكلي في الماء، مما يجعل تركيز أيونات الهيدرونيوم مساوياً لتركيز الحمض نفسه. ويستفاد من هذه العلاقة ومن قيمة ثابت تأين الماء (Kw) في إجراء الحسابات الكيميائية الدقيقة لإيجاد تركيز أيونات الهيدروكسيد في المحاليل الحمضية المختلفة.",
    "keyPoints": [
      "التأين الذاتي للماء هو تفاعل جزيئات الماء فيما بينها ليسلك بعضها كحمض والآخر كقاعدة.",
      "ثابت تأين الماء (Kw) هو القيمة الناتجة عن ضرب تركيز أيونات الهيدرونيوم في تركيز أيونات الهيدروكسيد ويساوي 1x10^-14 عند 25 درجة مئوية.",
      "تُصنف المحاليل إلى متعادلة، أو حمضية (تركيز الهيدرونيوم أكبر من 1x10^-7)، أو قاعدية (تركيز الهيدرونيوم أقل من 1x10^-7).",
      "تتأين الحموض القوية كلياً في المحلول المائي، ويكون تركيز أيونات الهيدرونيوم مساوياً لتركيز الحمض الابتدائي.",
      "يمكن حساب تركيز أيونات الهيدروكسيد في محلول حمض قوي باستخدام العلاقة الرياضية لثابت تأين الماء."
    ],
