        "back": "المعادلة هي:\nH₂O(l) + H₂O(l) ⇌ H₃O⁺(aq) + OH⁻(aq)\nحيث تشير الأسهم المتعاكسة (⇌) إلى حالة الاتزان الديناميكي بين جزيئات الماء غير المتأينة والأيونات الناتجة.",
