        "back": "يُفسر ذلك باحتواء الماء النقي على نسبة ضئيلة جداً من الأيونات الحرة (H₃O⁺ و OH⁻) الناتجة من تفاعل جزيئات الماء مع بعضها البعض (التأين الذاتي)، مما يسمح بمرور تيار كهربائي بسيط للغاية.",
